package org.deeptimeline.app
import android.content.Context
import org.json.JSONArray
import org.json.JSONObject
import java.math.BigDecimal
import java.math.BigInteger
import java.time.ZoneId
import java.time.ZoneOffset
import java.util.Locale
import java.util.UUID
data class TransferEntry(val index:Int,val title:String,val detail:String,val event:TimelineEvent?,val status:String,val defaultSelected:Boolean)
object EventJson{private fun field(json:JSONObject,key:String,default:String=""):String=if(json.has(key)&&!json.isNull(key))json.getString(key) else default;private fun fingerprint(event:TimelineEvent):String=event.title+"\u0000"+event.moment.second+"\u0000"+event.moment.nano+"\u0000"+event.mode+"\u0000"+event.coords+"\u0000"+event.zone;fun export(events:List<TimelineEvent>):String{val root=JSONObject();root.put("format","deep-timeline");root.put("version",1);val array=JSONArray();for(event in events){val civil=event.civil;val date=civil.substringBefore('T');val clock=civil.substringAfter('T',"00:00:00");val row=JSONObject();row.put("uuid",event.id);row.put("name",event.title);row.put("date",date);row.put("time",clock);row.put("mode",event.mode);if(event.coords.isNotBlank())row.put("coordinates",event.coords);if(event.zone.isNotBlank())row.put("zone",event.zone);row.put("epochSeconds",event.moment.second);row.put("nanosecond",event.moment.nano);row.put("offsetNanoseconds",event.offsetNano);row.put("created",event.created);row.put("updated",event.updated);if(event.maxScaleAmount.isNotBlank())row.put("maxVisibleSpan",JSONObject().put("value",event.maxScaleAmount).put("unit",event.maxScaleUnit));array.put(row)};root.put("events",array);return root.toString(2)+"\n"};fun template():String{val root=JSONObject();root.put("format","deep-timeline");root.put("version",1);val entries=JSONArray();entries.put(JSONObject().put("name","Example: Caesar's assassination").put("date","-44-03-15").put("time","12:00:00").put("mode","UTC").put("maxVisibleSpan",JSONObject().put("value","1/3").put("unit","DAY")));entries.put(JSONObject().put("name","Example: prehistoric event").put("date","-200000-01-01").put("mode","UTC").put("maxVisibleSpan",JSONObject().put("value","2^12").put("unit","YEAR")));entries.put(JSONObject().put("name","Example: longitude-based event").put("date","2026-01-01").put("time","09:00:00").put("mode","LONGITUDINAL").put("coordinates","29.9792, 31.1342").put("maxVisibleSpan",JSONObject().put("value","0.(3)").put("unit","MONTH")));root.put("events",entries);return root.toString(2)+"\n"};fun parse(context:Context,text:String,existing:List<TimelineEvent>):List<TransferEntry>{require(text.length<=67108864){"JSON file exceeds the 64 MiB import limit"};val root=JSONObject(text);require(field(root,"format","deep-timeline")=="deep-timeline"){"Not a Deep Timeline JSON file"};require(root.optInt("version",1)==1){"Unsupported JSON format version"};val rows=root.getJSONArray("events");require(rows.length()<=100000){"At most 100,000 events per import"};val byId=existing.associateBy{it.id};val fingerprints=existing.mapTo(HashSet()){fingerprint(it)};val fileIds=HashSet<String>();val fileFingerprints=HashSet<String>();val result=ArrayList<TransferEntry>(rows.length());for(i in 0 until rows.length()){var title="Event ${i+1}";var detail="";try{val json=rows.optJSONObject(i)?:throw IllegalArgumentException("Event must be a JSON object");title=field(json,"name");require(title.isNotBlank()){"Missing name"};require(title.length<=100000){"Name exceeds 100,000 characters"};val date=field(json,"date");val time=field(json,"time","00:00:00");val civil=TimeMath.parseCivil(date,time);val civilText=TimeMath.formatCivil(civil);detail="$date $time";val mode=field(json,"mode","UTC").uppercase(Locale.ROOT);require(mode in listOf("UTC","LOCAL","LONGITUDINAL")){"Mode must be UTC, LOCAL, or LONGITUDINAL"};val coordinate=field(json,"coordinates").trim();val location=if(coordinate.isNotBlank())Coordinates.parse(coordinate) else null;val zone=when(mode){"UTC"->"UTC";"LONGITUDINAL"->"";else->field(json,"zone").ifBlank{if(location==null)ZoneId.systemDefault().id else ZoneResolver.resolve(context,location.first.toDouble(),location.second.toDouble())?:throw IllegalArgumentException("Coordinates have no resolvable IANA timezone; supply zone")}};val canonical=if(json.has("epochSeconds")||json.has("nanosecond")){require(json.has("epochSeconds")&&json.has("nanosecond")){"Canonical timestamp needs epochSeconds and nanosecond together"};val nano=json.getInt("nanosecond");require(nano in 0..999999999){"Nanosecond outside valid range"};Moment(json.getLong("epochSeconds"),nano)}else null;val resolved=when(mode){"UTC"->{val value=TimeMath.fromUtc(civil);require(canonical==null||canonical==value){"UTC date disagrees with saved instant"};Pair(value,"0")};"LONGITUDINAL"->{require(location!=null){"Longitude mode requires coordinates"};val value=TimeMath.fromLongitude(civil,location.second);require(canonical==null||canonical==value.first){"Longitude-derived date disagrees with saved instant"};value};else->{val options=TimeMath.fromLocal(civil,zone).first;require(options.isNotEmpty()){"Local time does not exist in $zone"};val chosen=if(canonical!=null)options.firstOrNull{it.first==canonical}?:throw IllegalArgumentException("Saved instant disagrees with zone and date") else {require(options.size==1){"Ambiguous local time; supply epochSeconds and nanosecond to choose the offset"};options[0]};Pair(chosen.first,BigDecimal(ZoneOffset.of(chosen.second).totalSeconds).multiply(BigDecimal("1000000000")).toBigIntegerExact().toString())}};val offset=field(json,"offsetNanoseconds",resolved.second);require(runCatching{BigInteger(offset)}.isSuccess){"Invalid offsetNanoseconds"};require(offset==resolved.second){"Offset disagrees with date interpretation"};val uuid=field(json,"uuid",field(json,"id"));val id=if(uuid.isBlank())UUID.randomUUID().toString() else UUID.fromString(uuid).toString();require(fileIds.add(id)){"Repeated UUID in this file"};val old=byId[id];val now=System.currentTimeMillis();val limit=json.optJSONObject("maxVisibleSpan");require(!json.has("maxVisibleSpan")||limit!=null){"maxVisibleSpan must be an object"};val threshold=if(limit==null)Pair("","DAY") else {require(limit.opt("value") is String){"maxVisibleSpan.value must be a quoted string to preserve exact fractions and exponents"};VisibilityScale.normalize(field(limit,"value"),field(limit,"unit","DAY").uppercase(Locale.ROOT))};val event=TimelineEvent(id,title,resolved.first,civilText,mode,if(mode=="UTC")"" else coordinate,zone,offset,json.optLong("created",old?.created?:now),json.optLong("updated",now),threshold.first,threshold.second);val key=fingerprint(event);val repeated=!fileFingerprints.add(key);val same=old!=null&&fingerprint(old)==key&&old.civil==civilText&&old.offsetNano==offset&&old.maxScaleAmount==event.maxScaleAmount&&old.maxScaleUnit==event.maxScaleUnit;val duplicate=repeated||old==null&&key in fingerprints;val status=when{same->"UNCHANGED";old!=null->"UPDATE EXISTING";duplicate->"DUPLICATE";else->"NEW"};result.add(TransferEntry(i,title,detail,event,status,status=="NEW"||status=="UPDATE EXISTING"))}catch(e:Exception){result.add(TransferEntry(i,title,detail,null,"INVALID: ${e.message?:"Invalid event"}",false))}};return result}}
